-- ============================================================
-- CURRICULUM: boards × stages × groups × subjects
-- - Reference tables for BSEK, BIEK, AKU-EB, FBISE, Cambridge, Edexcel
--   (Grades 9–10 "secondary" and 11–12 "higher_secondary"; groups bio/comp/arts)
-- - courses / students: board + stage + group_code, subject as text with FKs
--   (replaces the 4-value board_type and 6-value subject_type enums)
-- - enquiries: stage + group_code
-- Source of truth: lib/curriculum.ts. The seed block below is generated by
-- scripts/generate-curriculum-sql.mjs. Safe to re-run.
-- ============================================================

-- ------------------------------------------------------------
-- Reference tables
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.curriculum_boards (
  code TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  short_name TEXT NOT NULL,
  family TEXT NOT NULL CHECK (family IN ('pakistan', 'international')),
  sort_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public.curriculum_subjects (
  code TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS public.curriculum_offerings (
  board TEXT NOT NULL REFERENCES public.curriculum_boards(code) ON UPDATE CASCADE,
  stage TEXT NOT NULL CHECK (stage IN ('secondary', 'higher_secondary')),
  label TEXT NOT NULL,
  note TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (board, stage)
);

CREATE TABLE IF NOT EXISTS public.curriculum_groups (
  board TEXT NOT NULL,
  stage TEXT NOT NULL,
  code TEXT NOT NULL CHECK (code IN ('bio', 'comp', 'arts')),
  name TEXT NOT NULL,
  electives_required INTEGER NOT NULL DEFAULT 0 CHECK (electives_required >= 0),
  note TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (board, stage, code),
  FOREIGN KEY (board, stage) REFERENCES public.curriculum_offerings(board, stage) ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.curriculum_group_subjects (
  board TEXT NOT NULL,
  stage TEXT NOT NULL,
  group_code TEXT NOT NULL,
  subject_code TEXT NOT NULL REFERENCES public.curriculum_subjects(code) ON UPDATE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('compulsory', 'core', 'elective')),
  sort_order INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (board, stage, group_code, subject_code),
  FOREIGN KEY (board, stage, group_code) REFERENCES public.curriculum_groups(board, stage, code) ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_curriculum_group_subjects_subject ON public.curriculum_group_subjects (subject_code);

-- Public read (the website shows the catalog), admin write.
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['curriculum_boards','curriculum_subjects','curriculum_offerings','curriculum_groups','curriculum_group_subjects']
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS "Anyone can read %1$s" ON public.%1$I', t);
    EXECUTE format('CREATE POLICY "Anyone can read %1$s" ON public.%1$I FOR SELECT TO anon, authenticated USING (true)', t);
    EXECUTE format('DROP POLICY IF EXISTS "Admins manage %1$s" ON public.%1$I', t);
    EXECUTE format('CREATE POLICY "Admins manage %1$s" ON public.%1$I FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin())', t);
  END LOOP;
END $$;

