-- ------------------------------------------------------------
-- courses: enum board/subject -> text + stage + group_code
-- Old values: aku_eb, sindh_board, cambridge_o, cambridge_a
-- ------------------------------------------------------------
ALTER TABLE public.courses ALTER COLUMN board TYPE TEXT USING board::text;
ALTER TABLE public.courses ALTER COLUMN subject TYPE TEXT USING subject::text;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS stage TEXT;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS group_code TEXT;

UPDATE public.courses SET stage = CASE WHEN board = 'cambridge_a' THEN 'higher_secondary' ELSE 'secondary' END
  WHERE board IS NOT NULL AND stage IS NULL;
UPDATE public.courses SET board = CASE board
    WHEN 'sindh_board' THEN 'bsek'
    WHEN 'cambridge_o' THEN 'cambridge'
    WHEN 'cambridge_a' THEN 'cambridge'
    ELSE board END
  WHERE board IN ('sindh_board', 'cambridge_o', 'cambridge_a');

ALTER TABLE public.courses DROP CONSTRAINT IF EXISTS courses_board_fkey;
ALTER TABLE public.courses DROP CONSTRAINT IF EXISTS courses_offering_fkey;
ALTER TABLE public.courses DROP CONSTRAINT IF EXISTS courses_group_fkey;
ALTER TABLE public.courses DROP CONSTRAINT IF EXISTS courses_subject_fkey;
ALTER TABLE public.courses DROP CONSTRAINT IF EXISTS courses_board_stage_check;
ALTER TABLE public.courses
  ADD CONSTRAINT courses_board_fkey FOREIGN KEY (board) REFERENCES public.curriculum_boards(code) ON UPDATE CASCADE,
  ADD CONSTRAINT courses_offering_fkey FOREIGN KEY (board, stage) REFERENCES public.curriculum_offerings(board, stage) ON UPDATE CASCADE,
  ADD CONSTRAINT courses_group_fkey FOREIGN KEY (board, stage, group_code) REFERENCES public.curriculum_groups(board, stage, code) ON UPDATE CASCADE,
  ADD CONSTRAINT courses_subject_fkey FOREIGN KEY (subject) REFERENCES public.curriculum_subjects(code) ON UPDATE CASCADE,
  ADD CONSTRAINT courses_board_stage_check CHECK ((board IS NULL) = (stage IS NULL) AND (group_code IS NULL OR board IS NOT NULL));

CREATE INDEX IF NOT EXISTS idx_courses_curriculum ON public.courses (board, stage, group_code);
CREATE INDEX IF NOT EXISTS idx_courses_subject ON public.courses (subject);

-- ------------------------------------------------------------
-- students: same treatment
-- ------------------------------------------------------------
ALTER TABLE public.students ALTER COLUMN board TYPE TEXT USING board::text;
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS stage TEXT;
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS group_code TEXT;

UPDATE public.students SET stage = CASE WHEN board = 'cambridge_a' THEN 'higher_secondary' ELSE 'secondary' END
  WHERE board IS NOT NULL AND stage IS NULL;
UPDATE public.students SET board = CASE board
    WHEN 'sindh_board' THEN 'bsek'
    WHEN 'cambridge_o' THEN 'cambridge'
    WHEN 'cambridge_a' THEN 'cambridge'
    ELSE board END
  WHERE board IN ('sindh_board', 'cambridge_o', 'cambridge_a');

ALTER TABLE public.students DROP CONSTRAINT IF EXISTS students_board_fkey;
ALTER TABLE public.students DROP CONSTRAINT IF EXISTS students_offering_fkey;
ALTER TABLE public.students DROP CONSTRAINT IF EXISTS students_group_fkey;
ALTER TABLE public.students DROP CONSTRAINT IF EXISTS students_board_stage_check;
ALTER TABLE public.students
  ADD CONSTRAINT students_board_fkey FOREIGN KEY (board) REFERENCES public.curriculum_boards(code) ON UPDATE CASCADE,
  ADD CONSTRAINT students_offering_fkey FOREIGN KEY (board, stage) REFERENCES public.curriculum_offerings(board, stage) ON UPDATE CASCADE,
  ADD CONSTRAINT students_group_fkey FOREIGN KEY (board, stage, group_code) REFERENCES public.curriculum_groups(board, stage, code) ON UPDATE CASCADE,
  ADD CONSTRAINT students_board_stage_check CHECK ((board IS NULL) = (stage IS NULL) AND (group_code IS NULL OR board IS NOT NULL));

CREATE INDEX IF NOT EXISTS idx_students_curriculum ON public.students (board, stage, group_code);

-- ------------------------------------------------------------
-- teachers.specialization: subject_type[] -> text[]
-- ------------------------------------------------------------
ALTER TABLE public.teachers ALTER COLUMN specialization TYPE TEXT[] USING specialization::text[];

-- ------------------------------------------------------------
-- enquiries: record what the applicant picked (validated by the API)
-- ------------------------------------------------------------
ALTER TABLE public.enquiries ADD COLUMN IF NOT EXISTS stage TEXT CHECK (stage IN ('secondary', 'higher_secondary'));
ALTER TABLE public.enquiries ADD COLUMN IF NOT EXISTS group_code TEXT CHECK (group_code IN ('bio', 'comp', 'arts'));

-- ------------------------------------------------------------
-- Old enums are no longer used by any column
-- ------------------------------------------------------------
DROP TYPE IF EXISTS public.board_type;
DROP TYPE IF EXISTS public.subject_type;
